  `ent_usu_anulado` int unsigned DEFAULT NULL,
  `ent_fec_anulado` datetime DEFAULT NULL,
  `ent_estado` int unsigned NOT NULL DEFAULT '1' COMMENT '0: Deshabilitado, 1: Habilitado, 2: Anulado',
  `usuario` int unsigned NOT NULL,
  `fechahora` datetime NOT NULL,
  `ip` varchar(20) DEFAULT NULL,
  `tipo_dispositivo` int unsigned DEFAULT NULL,
  `equipo` varchar(45) NOT NULL,
  PRIMARY KEY (`ent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=latin1;

