-- Volcando estructura para tabla ifact.facturacion
CREATE TABLE IF NOT EXISTS `facturacion` (
  `fac_id` int unsigned NOT NULL AUTO_INCREMENT,
  `fac_central_id` bigint DEFAULT NULL,
  `fac_id_externo` varchar(120) DEFAULT NULL,
  `fac_formato_pdf` enum('a4','ticket') DEFAULT NULL,
  `ven_id` int unsigned DEFAULT NULL,
  `ped_id` int unsigned DEFAULT NULL COMMENT 'Pedido relacionado',
  `fac_doc_referencia_id` int unsigned DEFAULT NULL,
  `fac_motivo_codigo` varchar(4) DEFAULT NULL,
  `fac_motivo_descripcion` varchar(500) DEFAULT NULL,
  `fac_tipo_valor` int unsigned NOT NULL COMMENT '1: Bien, 2: Servicio',
  `fac_tipo_operacion` varchar(4) NOT NULL,
  `fac_tipo_doc` varchar(4) NOT NULL,
  `fac_serie` varchar(4) NOT NULL,
  `fac_correlativo` varchar(8) NOT NULL,
  `fac_tipo_moneda` varchar(6) NOT NULL,
  `fac_tipo_cambio` decimal(4,3) NOT NULL DEFAULT '0.000',
  `fac_fecha_emision` datetime NOT NULL,
  `fac_empresa_ruc` varchar(11) NOT NULL DEFAULT '20614586231',
  `fac_cliente_tipo_doc` varchar(2) DEFAULT NULL,
  `fac_cliente_num_doc` varchar(11) DEFAULT NULL,
  `fac_cliente_razon_social` varchar(200) DEFAULT NULL,
  `fac_cliente_direccion` varchar(250) DEFAULT NULL,
  `fac_monto_oper_gravadas` float DEFAULT NULL,
  `fac_monto_oper_exoneradas` float DEFAULT NULL,
  `fac_monto_oper_inafectas` float DEFAULT NULL,
  `fac_monto_igv` float NOT NULL,
  `fac_total_impuestos` float DEFAULT NULL,
  `fac_valor_venta` float NOT NULL DEFAULT '0',
  `fac_sub_total` float NOT NULL,
  `fac_monto_imp_venta` float DEFAULT NULL,
  `fac_total_letras` varchar(300) DEFAULT NULL,
  `fac_url_cdr` text,
  `fac_url_xml` text,
  `fac_url_pdf` text,
  `fac_estado_sunat` varchar(20) DEFAULT NULL,
  `fac_respuesta_estado` varchar(30) DEFAULT NULL,
  `fac_respuesta_mensaje` text,
  `fac_respuesta_json` longtext,
  `fac_respuesta_fecha` datetime DEFAULT NULL,
  `fac_reintentos` int unsigned NOT NULL DEFAULT '0',
  `fac_ultimo_reintento` datetime DEFAULT NULL,
  `fac_proximo_reintento` datetime DEFAULT NULL,
  `fac_bloqueado_hasta` datetime DEFAULT NULL,
  `fac_fecha_aceptacion` datetime DEFAULT NULL,
  `fac_pdf_disponible` tinyint unsigned NOT NULL DEFAULT '0',
  `fac_xml_disponible` tinyint unsigned NOT NULL DEFAULT '0',
  `fac_cdr_disponible` tinyint unsigned NOT NULL DEFAULT '0',
  `fac_envio_email` int unsigned DEFAULT '0',
  `fac_envio_email_fecha` datetime DEFAULT NULL,
  `fac_estado` int unsigned NOT NULL,
  `usuario` int unsigned NOT NULL,
  `fechahora` datetime NOT NULL,
  PRIMARY KEY (`fac_id`),
  UNIQUE KEY `ped_id` (`ped_id`),
  KEY `ix_facturacion_central_id` (`fac_central_id`),
  KEY `idx_facturacion_referencia` (`fac_doc_referencia_id`),
  KEY `idx_facturacion_id_externo` (`fac_id_externo`),
  KEY `idx_facturacion_reintentos` (`fac_respuesta_estado`,`fac_proximo_reintento`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=latin1;

