CREATE TABLE IF NOT EXISTS `ingreso_stock` (
  `isi_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `loc_id` int unsigned NOT NULL,
  `isi_fecha` date NOT NULL,
  `isi_observacion` varchar(1000) DEFAULT NULL,
  `isi_items` int unsigned NOT NULL,
  `isi_cantidad` decimal(14,3) unsigned NOT NULL,
  `isi_estado` tinyint unsigned NOT NULL DEFAULT '1',
  `isi_clave` char(32) NOT NULL,
  `usuario` int unsigned NOT NULL,
  `fechahora` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`isi_id`),
  UNIQUE KEY `uq_ingreso_stock_clave` (`isi_clave`),
  KEY `idx_ingreso_stock_alm_fecha` (`loc_id`,`isi_fecha`),
  KEY `fk_ingreso_stock_usuario` (`usuario`),
  CONSTRAINT `fk_ingreso_stock_local` FOREIGN KEY (`loc_id`) REFERENCES `local` (`loc_id`),
  CONSTRAINT `fk_ingreso_stock_usuario` FOREIGN KEY (`usuario`) REFERENCES `usuario` (`usu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;

