-- Volcando estructura para tabla ifact.local
CREATE TABLE IF NOT EXISTS `local` (
  `loc_id` int unsigned NOT NULL AUTO_INCREMENT,
  `loc_nombre` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `loc_direccion` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `loc_ubigeo` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loc_telefono` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `loc_email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `loc_estado` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1 habilitado, 2 deshabilitado',
  `loc_usuario_creacion` int unsigned DEFAULT NULL,
  `loc_fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `loc_usuario_modificacion` int unsigned DEFAULT NULL,
  `loc_fecha_modificacion` datetime DEFAULT NULL,
  PRIMARY KEY (`loc_id`),
  KEY `ix_local_estado_nombre` (`loc_estado`,`loc_nombre`),
  KEY `fk_local_usuario_creacion` (`loc_usuario_creacion`),
  KEY `fk_local_usuario_modificacion` (`loc_usuario_modificacion`),
  CONSTRAINT `fk_local_usuario_creacion` FOREIGN KEY (`loc_usuario_creacion`) REFERENCES `usuario` (`usu_id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_local_usuario_modificacion` FOREIGN KEY (`loc_usuario_modificacion`) REFERENCES `usuario` (`usu_id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

