-- Volcando estructura para tabla ifact.movimiento
CREATE TABLE IF NOT EXISTS `movimiento` (
  `mov_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `loc_id` int unsigned NOT NULL,
  `mov_tipo` enum('INGRESO','EGRESO') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tmc_id` int unsigned DEFAULT NULL,
  `ent_id` int unsigned DEFAULT NULL,
  `mov_tipo_doc` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '00',
  `mov_serie` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mov_correlativo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mov_fecha` date NOT NULL,
  `mov_tipo_moneda` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PEN',
  `mov_tipo_cambio` decimal(10,4) NOT NULL DEFAULT '1.0000',
  `mov_subtotal` decimal(14,2) NOT NULL DEFAULT '0.00',
  `mov_igv` decimal(14,2) NOT NULL DEFAULT '0.00',
  `mov_total` decimal(14,2) NOT NULL,
  `mov_observaciones` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `mov_incluye_igv` tinyint unsigned NOT NULL DEFAULT '0',
  `mov_estado` tinyint unsigned NOT NULL DEFAULT '1',
  `mov_clave` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mov_usuario_creacion` int unsigned DEFAULT NULL,
  `mov_fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `mov_usuario_edicion` int unsigned DEFAULT NULL,
  `mov_fecha_edicion` datetime DEFAULT NULL,
  `mov_usuario_anulacion` int unsigned DEFAULT NULL,
  `mov_fecha_anulacion` datetime DEFAULT NULL,
  PRIMARY KEY (`mov_id`),
  UNIQUE KEY `uq_movimiento_clave` (`mov_clave`),
  KEY `ix_movimiento_local_fecha` (`loc_id`,`mov_fecha`),
  KEY `ix_movimiento_tipo_fecha` (`mov_tipo`,`mov_fecha`),
  KEY `fk_movimiento_tipo` (`tmc_id`),
  KEY `fk_movimiento_entidad` (`ent_id`),
  CONSTRAINT `fk_movimiento_entidad` FOREIGN KEY (`ent_id`) REFERENCES `entidad` (`ent_id`),
  CONSTRAINT `fk_movimiento_local` FOREIGN KEY (`loc_id`) REFERENCES `local` (`loc_id`),
  CONSTRAINT `fk_movimiento_tipo` FOREIGN KEY (`tmc_id`) REFERENCES `tipo_movimiento` (`tmc_id`),
  CONSTRAINT `chk_movimiento_estado` CHECK ((`mov_estado` in (1,2))),
  CONSTRAINT `chk_movimiento_total` CHECK ((`mov_total` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

