CREATE TABLE IF NOT EXISTS `movimiento_detalle` (
  `mde_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mov_id` bigint unsigned NOT NULL,
  `tmc_id` int unsigned NOT NULL,
  `mde_nombre` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `mde_unidad` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `mde_precio_unitario` decimal(14,2) NOT NULL DEFAULT '0.00',
  `mde_cantidad` decimal(14,3) NOT NULL DEFAULT '0.000',
  `mde_subtotal` decimal(14,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`mde_id`),
  KEY `ix_movimiento_detalle_movimiento` (`mov_id`),
  KEY `fk_movimiento_detalle_tipo` (`tmc_id`),
  CONSTRAINT `fk_movimiento_detalle_movimiento` FOREIGN KEY (`mov_id`) REFERENCES `movimiento` (`mov_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_movimiento_detalle_tipo` FOREIGN KEY (`tmc_id`) REFERENCES `tipo_movimiento` (`tmc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1063 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

