CREATE TABLE IF NOT EXISTS `movimiento_pago` (
  `mpa_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mov_id` bigint unsigned NOT NULL,
  `mpa_fecha` date NOT NULL,
  `tpa_id` int unsigned NOT NULL,
  `cba_id` int unsigned NOT NULL,
  `mpa_medio` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `mpa_numero_operacion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
