  `mpa_fecha_anulacion` datetime DEFAULT NULL,
  PRIMARY KEY (`mpa_id`),
  UNIQUE KEY `uq_movimiento_pago_clave` (`mpa_clave`),
  KEY `ix_movimiento_pago_movimiento` (`mov_id`),
  KEY `fk_movimiento_pago_medio` (`tpa_id`),
  KEY `fk_movimiento_pago_cuenta` (`cba_id`),
  CONSTRAINT `fk_movimiento_pago_cuenta` FOREIGN KEY (`cba_id`) REFERENCES `cuenta_bancaria` (`cba_id`),
  CONSTRAINT `fk_movimiento_pago_medio` FOREIGN KEY (`tpa_id`) REFERENCES `tipo_pago` (`tpa_id`),
  CONSTRAINT `fk_movimiento_pago_movimiento` FOREIGN KEY (`mov_id`) REFERENCES `movimiento` (`mov_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_movimiento_pago_estado` CHECK ((`mpa_estado` in (1,2))),
  CONSTRAINT `chk_movimiento_pago_monto` CHECK ((`mpa_monto` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

