-- Volcando estructura para tabla ifact.movimiento_stock_variante
CREATE TABLE IF NOT EXISTS `movimiento_stock_variante` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pva_id` int unsigned NOT NULL,
  `loc_id` int unsigned NOT NULL,
  `cantidad` decimal(14,3) NOT NULL,
  `tipo` tinyint NOT NULL COMMENT '1 ingreso, 2 venta, 3 devolución por anulación, 4 reversión de ingreso, 5 ajuste positivo, 6 ajuste negativo',
  `ven_id` int unsigned DEFAULT NULL,
  `isi_id` bigint unsigned DEFAULT NULL,
  `aji_id` bigint unsigned DEFAULT NULL,
  `usuario` int unsigned NOT NULL,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ven_id` (`ven_id`),
  KEY `pva_id` (`pva_id`),
  KEY `idx_movimiento_ingreso` (`isi_id`),
  KEY `idx_movimiento_ajuste` (`aji_id`),
  CONSTRAINT `movimiento_stock_variante_ibfk_1` FOREIGN KEY (`pva_id`) REFERENCES `producto_variante` (`pva_id`)
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=latin1;

