-- Volcando estructura para tabla ifact.producto
CREATE TABLE IF NOT EXISTS `producto` (
  `pro_id` int unsigned NOT NULL AUTO_INCREMENT,
  `pro_nombre` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `und_med` int unsigned NOT NULL,
  `pro_costo_prod` decimal(12,2) unsigned NOT NULL DEFAULT '0.00',
  `pro_costo_admin` decimal(12,2) unsigned NOT NULL DEFAULT '0.00',
  `pro_porc_ganancia` float unsigned NOT NULL DEFAULT '0',
  `pro_prec_sugerido` decimal(12,2) unsigned NOT NULL DEFAULT '0.00',
  `pro_prec_venta` decimal(12,2) NOT NULL DEFAULT '0.00',
  `pro_cant_minima` float NOT NULL DEFAULT '0' COMMENT 'Cantidad mínima de stock para alertas',
  `pro_imagen` varchar(255) DEFAULT NULL COMMENT 'Path de la imagen',
  `pro_usu_ult_edicion` int unsigned DEFAULT NULL,
  `pro_fec_ult_edicion` datetime DEFAULT NULL,
  `pro_usu_anulado` int unsigned DEFAULT NULL,
  `pro_fec_anulado` datetime DEFAULT NULL,
  `pro_estado` int unsigned NOT NULL DEFAULT '1' COMMENT '0: Deshabilitado, 1: Habilitado, 2: Anulado',
  `usuario` int unsigned NOT NULL,
  `fechahora` datetime NOT NULL,
  `ip` varchar(25) DEFAULT NULL,
  `tipo_dispositivo` int unsigned DEFAULT NULL,
  `equipo` varchar(45) DEFAULT NULL,
  `cat_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`pro_id`),
  KEY `fk_producto_unidad_medida` (`und_med`),
  KEY `fk_producto_categoria` (`cat_id`),
  CONSTRAINT `fk_producto_categoria` FOREIGN KEY (`cat_id`) REFERENCES `categoria` (`cat_id`),
  CONSTRAINT `fk_producto_unidad_medida` FOREIGN KEY (`und_med`) REFERENCES `unidad_medida` (`und_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1125 DEFAULT CHARSET=latin1;

