-- Volcando estructura para tabla ifact.tipo_movimiento
CREATE TABLE IF NOT EXISTS `tipo_movimiento` (
  `tmc_id` int unsigned NOT NULL AUTO_INCREMENT,
  `tmc_tipo` enum('INGRESO','EGRESO') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tmc_nombre` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tmc_clase` enum('INSUMO','MERCADERIA','SERVICIO','GASTO') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tmc_unidad` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'UND',
  `tmc_estado` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1 habilitado, 0 deshabilitado, 2 eliminado',
  `tmc_usuario_creacion` int unsigned NOT NULL,
  `tmc_fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tmc_usuario_modificacion` int unsigned DEFAULT NULL,
  `tmc_fecha_modificacion` datetime DEFAULT NULL,
  `tmc_usuario_eliminacion` int unsigned DEFAULT NULL,
  `tmc_fecha_eliminacion` datetime DEFAULT NULL,
  PRIMARY KEY (`tmc_id`),
  UNIQUE KEY `uq_tipo_movimiento` (`tmc_tipo`,`tmc_nombre`),
  KEY `ix_tipo_movimiento_estado` (`tmc_estado`,`tmc_tipo`),
  KEY `fk_tmc_usuario_creacion` (`tmc_usuario_creacion`),
  KEY `fk_tmc_usuario_modificacion` (`tmc_usuario_modificacion`),
  KEY `fk_tmc_usuario_eliminacion` (`tmc_usuario_eliminacion`),
  CONSTRAINT `fk_tmc_usuario_creacion` FOREIGN KEY (`tmc_usuario_creacion`) REFERENCES `usuario` (`usu_id`),
  CONSTRAINT `fk_tmc_usuario_eliminacion` FOREIGN KEY (`tmc_usuario_eliminacion`) REFERENCES `usuario` (`usu_id`),
  CONSTRAINT `fk_tmc_usuario_modificacion` FOREIGN KEY (`tmc_usuario_modificacion`) REFERENCES `usuario` (`usu_id`),
  CONSTRAINT `chk_tmc_estado` CHECK ((`tmc_estado` in (0,1,2)))
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

