-- Volcando estructura para tabla ifact.venta
CREATE TABLE IF NOT EXISTS `venta` (
  `ven_id` int unsigned NOT NULL AUTO_INCREMENT,
  `loc_id` int unsigned NOT NULL,
  `ven_tipo` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:Insumo, 2:Producto',
  `usu_id` int unsigned NOT NULL COMMENT 'Usuario que registra',
  `ent_id` int unsigned DEFAULT NULL,
  `tde_id` int unsigned DEFAULT NULL COMMENT 'tipo_doc_elect.tde_id',
  `ven_serie` varchar(4) DEFAULT NULL COMMENT 'Serie del comprobante',
  `ven_numero` int unsigned DEFAULT NULL COMMENT 'Correlativo del comprobante',
  `ven_nota_serie` varchar(4) DEFAULT NULL,
  `ven_nota_numero` bigint unsigned DEFAULT NULL,
  `ven_fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ven_tipo_moneda` varchar(3) NOT NULL DEFAULT 'PEN',
  `ven_tipo_cambio` decimal(4,3) NOT NULL DEFAULT '0.000',
  `ven_total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `ven_subtotal` decimal(10,2) DEFAULT NULL COMMENT 'Subtotal sin IGV',
  `ven_igv` decimal(10,2) DEFAULT NULL COMMENT 'Monto IGV 18%',
  `fac_id` int DEFAULT NULL,
  `ven_tpa_id` int unsigned DEFAULT NULL COMMENT 'tipo_pago.tpa_id',
  `ven_num_operacion` varchar(100) DEFAULT NULL,
  `ven_comentario` text,
  `ven_estado` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=Activo, 0=Anulado',
  `ven_usu_anulado` int unsigned DEFAULT NULL,
  `ven_fec_anulado` datetime DEFAULT NULL,
  `ven_ip` varchar(45) DEFAULT NULL,
  `ven_cba_id` int unsigned DEFAULT NULL,
  `ven_pagado` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`ven_id`),
  UNIQUE KEY `uk_venta_serie_numero` (`ven_serie`,`ven_numero`),
  UNIQUE KEY `uq_venta_nota_numero` (`ven_nota_serie`,`ven_nota_numero`),
  KEY `idx_ven_alm` (`loc_id`),
  KEY `idx_ven_usu` (`usu_id`),
  KEY `idx_ven_fecha` (`ven_fecha`),
  KEY `idx_ven_entidad` (`ent_id`),
  CONSTRAINT `fk_venta_local` FOREIGN KEY (`loc_id`) REFERENCES `local` (`loc_id`),
  CONSTRAINT `fk_venta_usuario` FOREIGN KEY (`usu_id`) REFERENCES `usuario` (`usu_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=latin1;

