-- Volcando estructura para tabla ifact.venta_pago
CREATE TABLE IF NOT EXISTS `venta_pago` (
  `vpa_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ven_id` int unsigned NOT NULL,
  `tpa_id` int unsigned NOT NULL,
  `cba_id` int unsigned NOT NULL,
  `monto` decimal(10,2) NOT NULL,
  `num_operacion` varchar(100) DEFAULT NULL,
  `usuario` int unsigned NOT NULL,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `clave` char(32) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  PRIMARY KEY (`vpa_id`),
  UNIQUE KEY `uq_pago_clave` (`clave`),
  KEY `ven_id` (`ven_id`),
  KEY `fk_venta_pago_tipo` (`tpa_id`),
  KEY `fk_venta_pago_cuenta` (`cba_id`),
  KEY `fk_venta_pago_usuario` (`usuario`),
  CONSTRAINT `fk_venta_pago_cuenta` FOREIGN KEY (`cba_id`) REFERENCES `cuenta_bancaria` (`cba_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_venta_pago_tipo` FOREIGN KEY (`tpa_id`) REFERENCES `tipo_pago` (`tpa_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_venta_pago_usuario` FOREIGN KEY (`usuario`) REFERENCES `usuario` (`usu_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `venta_pago_ibfk_1` FOREIGN KEY (`ven_id`) REFERENCES `venta` (`ven_id`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=latin1;

